// TASK-0043 — V1 Automatic Watcher & Reconciliation, product acceptance in real
// WebView2. No simulated DOM, no alternate renderer, no personal data: the trees under
// test were generated by task0043-seed-proof.py and die with the proof root.
//
// The claim under test: FileTopo keeps a brain's Index in step with a source that changes
// OUTSIDE the process — **without a single click on Actualiser** — and a source that leaves
// is an observation, never a batch of deletions. Every filesystem change below is made by
// THIS script directly on disk, outside the product process, between the moments it reads
// the real screen.
//
//   phase 1  (process 1)  baseline (the one and only Actualiser click) -> the watcher
//            starts by itself: STARTING/VERIFYING then WATCHING -> external creations,
//            edits, deletions, renames and moves appear in the map, the journal and the
//            new / unseen filter without a click -> a burst of ~1 500 external operations
//            converges to exactly what is on disk -> the whole root is MOVED away: the
//            watcher says DEGRADED / source unavailable, the map stays, zero DELETED ->
//            the same folder comes back: VERIFYING (source returned) then WATCHING and
//            SYNCED, nothing invented -> a second brain is watched independently.
//   phase 0  (no application running) — the real process was closed by the .ps1; this
//            script changes the source while FileTopo is CLOSED.
//   phase 2  (process 2)  the relaunched application catches up by itself: no click, the
//            Index equals the disk at the first stable state, both brains.
//
// Every event the backend emits is recorded from the page (`map-watch-status`) and checked
// for the closed envelope: seven keys, closed words, no path, no name, no key, no identity.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, rename, rm, stat, writeFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0043-[a-f0-9]+$/.test(variant));
assert(phase === 0 || phase === 1 || phase === 2);

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainA, rootA, brainB, rootB } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const heldA = `${rootA}-deplace`;
const WATCH_KEYS = ["brainId", "indexRevision", "mode", "pending", "reason", "sequence", "state"];

const exists = async (path) => {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
};
/** Every entry below `dir`, files and directories, `dir` itself excluded. */
async function countEntries(dir) {
  let total = 0;
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    total += 1;
    if (entry.isDirectory()) total += await countEntries(join(dir, entry.name));
  }
  return total;
}
/** What the Index must hold for a root: every entry below it, plus the root itself. */
const expectedNodes = async (dir) => (await countEntries(dir)) + 1;

// ---- phase 0: the application is CLOSED; the source moves on -------------------------
if (phase === 0) {
  const before = JSON.parse(await readFile(join(proofRoot, "phase1.json"), "utf8"));
  assert(before.snapshot.revision > 0);
  // ~3 000 new files, deleted files, a rename, a move, a top-level change, a new tree.
  for (let group = 0; group < 30; group++) {
    const dir = join(rootA, "dossier", "hors-ligne", `h${String(group).padStart(2, "0")}`);
    await mkdir(dir, { recursive: true });
    for (let file = 0; file < 100; file++) {
      await writeFile(join(dir, `f${String(file).padStart(3, "0")}.txt`), "synthetique — cree hors ligne\n", "utf8");
    }
  }
  for (let file = 0; file < 50; file++) {
    await rm(join(rootA, "gros", "g05", `f${String(file).padStart(3, "0")}.txt`), { force: true });
  }
  await writeFile(join(rootA, "dossier", "enfant.txt"), "synthetique — enfant modifie hors ligne, plus long\n", "utf8");
  await rename(join(rootA, "dossier", "sous", "profond.txt"), join(rootA, "dossier", "sous", "profond-renomme.txt"));
  await rename(join(rootA, "dossier", "sous", "autre.txt"), join(rootA, "vide", "autre-deplace.txt"));
  await writeFile(join(rootA, "hors-ligne-au-sommet.txt"), "synthetique — au sommet\n", "utf8");
  // And the second brain, closed as well.
  await writeFile(join(rootB, "docs", "hors-ligne-b.txt"), "synthetique — B hors ligne\n", "utf8");
  await rm(join(rootB, "archive", "x.txt"), { force: true });
  const offline = {
    expectedNodesA: await expectedNodes(rootA),
    expectedNodesB: await expectedNodes(rootB),
  };
  await writeFile(join(proofRoot, "offline.json"), JSON.stringify(offline));
  console.log(JSON.stringify({ ok: true, phase, ...offline }));
  process.exit(0);
}

// ---- CDP attach --------------------------------------------------------------------
let target;
for (let n = 0; n < 150; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(100);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
// Every `map_*` IPC round trip the PRODUCT itself makes, observed on the wire (CDP Network),
// in order. The harness's own `invoke` calls go through Runtime.evaluate and are recorded
// apart, so they can never be mistaken for what the product did.
const wireRequests = new Map();
const wireStatus = new Map();
const wireCalls = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.method === "Network.requestWillBeSent") {
    const url = event.params.request.url;
    const m = /\/(map_[a-z_]+)(?:[?#].*)?$/.exec(url);
    // The POST only: a custom-protocol request may be preceded by a CORS preflight, which
    // would otherwise count the same command twice.
    if (m && /ipc/.test(url) && event.params.request.method === "POST") wireRequests.set(event.params.requestId, m[1]);
  } else if (event.method === "Network.responseReceived" && wireRequests.has(event.params.requestId)) {
    const headers = event.params.response.headers ?? {};
    const outcome = Object.entries(headers).find(([name]) => name.toLowerCase() === "tauri-response")?.[1];
    wireStatus.set(event.params.requestId, event.params.response.status === 200 && outcome !== "error" ? 200 : 500);
  } else if (event.method === "Network.loadingFinished" && wireRequests.has(event.params.requestId)) {
    const id = event.params.requestId;
    wireCalls.push({ command: wireRequests.get(id), ok: (wireStatus.get(id) ?? 200) === 200 });
    wireRequests.delete(id);
  } else if (event.method === "Network.loadingFailed" && wireRequests.has(event.params.requestId)) {
    wireCalls.push({ command: wireRequests.get(event.params.requestId), ok: false });
    wireRequests.delete(event.params.requestId);
  }
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
/** Polls a Node-side predicate. */
async function untilTrue(description, predicate, limit = 240000, interval = 150) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await predicate()) return;
    await pause(interval);
  }
  throw new Error(`timeout: ${description}`);
}
const exposedPayloads = [];
// The harness's own reads (never a product click). `map_open`, `map_source_observation`,
// `map_view`, `map_change_journal` and `map_watch_status` read FileTopo's own local state
// and none of them touches the source. The one exception is `map_refresh` for the SECOND
// brain, called once as its baseline — the very command Actualiser calls.
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`,
  );
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");
await send("Network.enable", { maxTotalBufferSize: 64 * 1024 * 1024, maxResourceBufferSize: 16 * 1024 * 1024 });

async function key(k) {
  const vk = k === "Enter" ? 13 : k === " " ? 32 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k === " " ? "Space" : k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
    ...(k === " " ? { text: " ", unmodifiedText: " " } : {}),
  });
  await send("Input.dispatchKeyEvent", {
    type: "keyUp",
    key: k,
    code: k === " " ? "Space" : k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
  });
  await pause(120);
}
async function activate(selector, k = "Enter") {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key(k);
}
const jargon = [
  "stable_key",
  "stableKey",
  "identity_provenance",
  "identityProvenance",
  "SYS1:",
  "PFv1:",
  "PATH_FALLBACK",
  "fileId",
  "file_id",
  "volumeSerial",
  "volume_serial",
];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
function assertNoPathLeak(text, where) {
  for (const path of [rootA, heldA, rootB]) {
    const escaped = path.split("\\").join("\\\\");
    assert(!text.includes(path) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
  assert(!/os error/i.test(text), `a raw OS message leaked into ${where}`);
}

// ---- the watcher's own event, recorded from the page ---------------------------------
async function installRecorder() {
  await until(`!!window.__TAURI_INTERNALS__`);
  await evaluate(`(async () => {
    window.__watchEvents = [];
    const handler = window.__TAURI_INTERNALS__.transformCallback((event) => window.__watchEvents.push(event.payload));
    await window.__TAURI_INTERNALS__.invoke('plugin:event|listen', { event: 'map-watch-status', target: { kind: 'Any' }, handler });
    return true;
  })()`);
}
const recorded = () => evaluate(`JSON.parse(JSON.stringify(window.__watchEvents ?? []))`);
const recordedFor = async (brainId) => (await recorded()).filter((event) => event.brainId === brainId);
async function assertConfidential() {
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
  // Every backend event: exactly the closed envelope, and nothing that names a place.
  const events = await recorded();
  for (const event of events) {
    assert.deepEqual(Object.keys(event).sort(), WATCH_KEYS, "an event carries exactly the closed envelope");
    const text = JSON.stringify(event);
    assertNoPathLeak(text, "a watcher event");
    assertNoJargon(text, "a watcher event");
  }
  return events.length;
}

// ---- what the real screen shows -------------------------------------------------------
